function reverseWords(s: string): string {
  const words: string[] = [];
  let i = s.length - 1;

  // Идём с конца строки и вырезаем слова справа налево
  while (i >= 0) {
    // Пропускаем пробелы
    while (i >= 0 && s[i] === ' ') i--;
    if (i < 0) break;

    // end — индекс за последним символом слова
    const end = i + 1;
    // Ищем начало слова
    while (i >= 0 && s[i] !== ' ') i--;

    // Слова попадают в массив уже в обратном порядке
    words.push(s.slice(i + 1, end));
  }

  return words.join(' ');
}

// Время: O(n)
// Память: O(n) — массив слов и результат (строки в JS неизменяемы)
